namespace Archy.Features.Placement.AdviseSplitOrAppend;
/// <summary>Explains a non-blocking append/new-file recommendation from module scale, cohesion, fan-out, and available naming evidence.</summary>
public sealed class SplitAppendAdvisor(SplitAppendThresholds thresholds) : ISplitAppendAdvisor
{
 public SplitAppendAdvice Advise(SplitAppendInput input){ArgumentNullException.ThrowIfNull(input);if(string.IsNullOrWhiteSpace(input.ModuleKey)||input.MemberCount<1||!double.IsFinite(input.Cohesion)||input.Cohesion is<0 or>1||!double.IsFinite(input.FanIn)||input.FanIn<0||!double.IsFinite(input.FanOut)||input.FanOut<0||thresholds.LargeModuleMemberCount<1||!double.IsFinite(thresholds.LowCohesionThreshold)||thresholds.LowCohesionThreshold is<0 or>1||!double.IsFinite(thresholds.HighFanOutThreshold)||thresholds.HighFanOutThreshold<0)throw new ArgumentException("Split/append advice requires bounded module metrics and thresholds.",nameof(input));var split=input.MemberCount>=thresholds.LargeModuleMemberCount&&input.Cohesion<=thresholds.LowCohesionThreshold&&input.FanOut>=thresholds.HighFanOutThreshold;if(split&&input.SuggestedFileName is not null)return new(SplitAppendAdviceKind.CreateNewFile,"Large low-cohesion module with high fan-out; keep the new responsibility isolated.",input.SuggestedFileName);if(!split&&input.MemberCount<thresholds.LargeModuleMemberCount&&input.Cohesion>thresholds.LowCohesionThreshold)return new(SplitAppendAdviceKind.Append,"Small cohesive module; appending preserves the existing local boundary.",null);return new(SplitAppendAdviceKind.Abstain,"Module metrics or naming evidence are insufficient for a safe file-placement recommendation.",null); }
}
